/**
 * Names for the API's response bodies. Every type comes from the OpenAPI document
 * (`schema.d.ts`, generated by `pnpm gen:api`), so the server's response models are the single
 * source of truth. Nothing here validates at runtime.
 */
import type { components } from "./schema";

type S = components["schemas"];

export type Project = S["ProjectOut"];
export type Agent = S["AgentOut"];
export type AgentVersion = S["AgentVersionOut"];
export type Target = AgentVersion["target"];
export type Profile = S["AgentProfile"];

export type ScenarioDoc = S["Scenario"];
export type ScenarioRecord = S["ScenarioRecord"];
export type Suite = S["SuiteOut"];
export type ToolSpec = S["ToolSpec"];
export type World = S["WorldDoc"];

export type Counts = S["RunCounts"];
export type Run = S["RunOut"];
export type Estimate = S["DryRunOut"];

export type EpisodeRow = S["EpisodeRow"];
export type EpisodeEvent = S["Event"];
export type Evidence = S["Evidence"];
export type Verdict = S["Verdict"];
export type DiffChange = S["RecordChange"];
export type EpisodeDetail = S["EpisodeDetail"];
export type Report = S["RunReport"];

/** `POST /v1/runs` answers a dry run with `valid`, a created run with `id`. */
export const isDryRun = (r: S["RunOut"] | S["DryRunOut"]): r is S["DryRunOut"] => "valid" in r;

/** Terminal run statuses (contract: runs.status). */
export const TERMINAL_RUN_STATUSES = ["done", "cancelled", "failed"] as const;
export const isTerminalRun = (status: string) =>
  (TERMINAL_RUN_STATUSES as readonly string[]).includes(status);

export type ModelCatalogEntry = S["CatalogModel"];
export type ModelSettings = S["ModelSettingsOut"];
export type RoleChoice = S["RoleChoice"];
